PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE audit_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    action TEXT NOT NULL,
    resource_type TEXT,
    resource_id TEXT,
    user_email TEXT,
    details TEXT,
    ip_address TEXT,
    user_agent TEXT,
    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE iccid_mappings (
          id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
          iccid TEXT UNIQUE NOT NULL,
          phone_number TEXT NOT NULL,
          carrier TEXT,
          country TEXT,
          notes TEXT,
          is_active INTEGER DEFAULT 1,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          created_by TEXT,
          updated_by TEXT
        );
CREATE TABLE ai_insights (
    message_id TEXT PRIMARY KEY,
    classification TEXT,
    verification_code TEXT,
    confidence_score REAL,
    sender_category TEXT,
    language TEXT,
    is_spam BOOLEAN DEFAULT FALSE,
    urgency TEXT CHECK(urgency IN ('high', 'medium', 'low')),
    extracted_entities JSON,
    extracted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (message_id) REFERENCES messages(id) ON DELETE CASCADE
);
CREATE TABLE chat_conversations (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,  -- Auth0 user ID (sub claim)
    started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    last_message_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    message_count INTEGER DEFAULT 0,
    context JSON
);
CREATE TABLE chat_messages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    conversation_id TEXT NOT NULL,
    role TEXT CHECK(role IN ('user', 'assistant', 'system')) NOT NULL,
    content TEXT NOT NULL,
    function_calls JSON,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (conversation_id) REFERENCES chat_conversations(id) ON DELETE CASCADE
);
CREATE TABLE ai_function_calls (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    conversation_id TEXT,
    function_name TEXT NOT NULL,
    parameters JSON,
    result JSON,
    success BOOLEAN DEFAULT TRUE,
    error_message TEXT,
    execution_time_ms INTEGER,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (conversation_id) REFERENCES chat_conversations(id) ON DELETE CASCADE
);
CREATE TABLE keyword_tags (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    keyword TEXT NOT NULL,
    tag TEXT NOT NULL,
    color TEXT DEFAULT '#3B82F6', -- Default blue color
    priority INTEGER DEFAULT 0, -- Higher priority keywords take precedence
    is_active BOOLEAN DEFAULT TRUE,
    case_sensitive BOOLEAN DEFAULT FALSE,
    whole_word BOOLEAN DEFAULT FALSE, -- Match whole words only
    created_by TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE message_tags (
    message_id TEXT NOT NULL,
    keyword_tag_id INTEGER NOT NULL,
    matched_text TEXT NOT NULL, -- The actual text that matched
    position INTEGER NOT NULL, -- Starting position in message
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (message_id, keyword_tag_id, position),
    FOREIGN KEY (message_id) REFERENCES messages(id) ON DELETE CASCADE,
    FOREIGN KEY (keyword_tag_id) REFERENCES keyword_tags(id) ON DELETE CASCADE
);
CREATE TABLE daemon_health (
          daemon_id TEXT PRIMARY KEY,
          last_heartbeat TIMESTAMP NOT NULL,
          status TEXT DEFAULT 'online',
          last_ip TEXT,
          version TEXT,
          modem_count INTEGER DEFAULT 0,
          error_count INTEGER DEFAULT 0,
          last_error TEXT,
          metadata TEXT,
          created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
          updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE modems (
    equipment_id TEXT PRIMARY KEY,        -- IMEI from mmcli (e.g., "865827078383361")
    manufacturer TEXT,                    -- e.g., "QUALCOMM INCORPORATED"
    model TEXT,                           -- e.g., "QUECTEL Mobile Broadband Module"
    firmware_revision TEXT,               -- e.g., "EC20CEHDLGR08A02M1G"
    hardware_revision TEXT,               -- e.g., "10000"
    device_path TEXT,                     -- e.g., "/org/freedesktop/ModemManager1/Modem/66"
    usb_port INTEGER,                     -- Physical USB port number
    modem_index INTEGER,                  -- mmcli modem index (transient)
    status TEXT DEFAULT 'disconnected',  -- connected, disconnected, error
    last_seen TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    first_seen TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    error_count INTEGER DEFAULT 0,
    last_error TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE sims (
    iccid TEXT PRIMARY KEY,              -- SIM card identifier
    phone_number TEXT,                   -- Phone number assigned to SIM
    country_code TEXT,                   -- ISO country code
    carrier TEXT,                        -- Carrier name
    operator_name TEXT,                  -- Current operator
    operator_id TEXT,                    -- MCC/MNC
    current_modem_id TEXT,               -- FK to modems.equipment_id
    status TEXT DEFAULT 'inactive',      -- active, inactive, removed
    activation_date TIMESTAMP,
    deactivation_date TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, sim_index INTEGER,
    FOREIGN KEY (current_modem_id) REFERENCES modems(equipment_id) ON DELETE SET NULL
);
CREATE TABLE modem_sim_history (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    modem_id TEXT NOT NULL,
    sim_iccid TEXT NOT NULL,
    inserted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    removed_at TIMESTAMP,
    signal_quality INTEGER,              -- Last known signal quality
    network_type TEXT,                   -- Last known network type (GSM, LTE, etc.)
    access_tech TEXT,                    -- Last known access technology
    FOREIGN KEY (modem_id) REFERENCES modems(equipment_id) ON DELETE CASCADE,
    FOREIGN KEY (sim_iccid) REFERENCES sims(iccid) ON DELETE CASCADE
);
CREATE TABLE modem_state (
    modem_id TEXT PRIMARY KEY,
    signal_percent INTEGER,
    rssi INTEGER,
    rsrq INTEGER,
    rsrp INTEGER,
    snr INTEGER,
    network_type TEXT,
    access_tech TEXT,
    connection_status TEXT,              -- registered, searching, denied
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (modem_id) REFERENCES modems(equipment_id) ON DELETE CASCADE
);
CREATE TABLE schema_version (
    version INTEGER PRIMARY KEY,
    applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    description TEXT
);
CREATE TABLE IF NOT EXISTS "messages" (
    id TEXT PRIMARY KEY,
    phone_iccid TEXT NOT NULL,
    phone_number TEXT,
    content TEXT NOT NULL,
    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
    type TEXT NOT NULL,
    recipient TEXT,
    status TEXT DEFAULT 'received',
    verification_code TEXT,
    sms_id TEXT,
    error_message TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    ai_verification_code TEXT,
    ai_confidence REAL,
    ai_classification TEXT,
    sim_iccid TEXT,
    modem_id TEXT
);
CREATE TABLE message_embeddings (message_id TEXT PRIMARY KEY, embedding BLOB, model_version TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (message_id) REFERENCES messages(id) ON DELETE CASCADE);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_audit_logs_timestamp ON audit_logs(timestamp);
CREATE INDEX idx_audit_logs_user_email ON audit_logs(user_email);
CREATE INDEX idx_iccid_mappings_iccid ON iccid_mappings(iccid);
CREATE INDEX idx_iccid_mappings_phone ON iccid_mappings(phone_number);
CREATE INDEX idx_iccid_mappings_active ON iccid_mappings(is_active);
CREATE INDEX idx_chat_conversations_user_id ON chat_conversations(user_id);
CREATE INDEX idx_chat_conversations_last_message ON chat_conversations(last_message_at DESC);
CREATE INDEX idx_chat_messages_conversation ON chat_messages(conversation_id);
CREATE INDEX idx_chat_messages_created ON chat_messages(created_at DESC);
CREATE INDEX idx_ai_function_calls_conversation ON ai_function_calls(conversation_id);
CREATE INDEX idx_ai_function_calls_function ON ai_function_calls(function_name);
CREATE INDEX idx_ai_function_calls_created ON ai_function_calls(created_at);
CREATE INDEX idx_keyword_tags_keyword ON keyword_tags(keyword);
CREATE INDEX idx_keyword_tags_active ON keyword_tags(is_active);
CREATE INDEX idx_keyword_tags_priority ON keyword_tags(priority DESC);
CREATE INDEX idx_message_tags_message_id ON message_tags(message_id);
CREATE INDEX idx_message_tags_keyword_tag_id ON message_tags(keyword_tag_id);
CREATE INDEX idx_message_tags_message ON message_tags(message_id);
CREATE INDEX idx_message_tags_keyword ON message_tags(keyword_tag_id);
CREATE INDEX idx_sims_current_modem ON sims(current_modem_id);
CREATE INDEX idx_sims_status ON sims(status);
CREATE INDEX idx_modems_status ON modems(status);
CREATE INDEX idx_modems_usb_port ON modems(usb_port);
CREATE INDEX idx_modem_sim_history_dates ON modem_sim_history(inserted_at, removed_at);
CREATE INDEX idx_modem_state_updated ON modem_state(updated_at);
CREATE INDEX idx_sims_modem_lookup ON sims(current_modem_id, status);
CREATE INDEX idx_modem_state_lookup ON modem_state(modem_id, updated_at DESC);
CREATE INDEX idx_sims_sim_index ON sims(sim_index);
CREATE INDEX idx_modems_modem_index ON modems(modem_index);
CREATE INDEX idx_modem_state_status ON modem_state(connection_status);
CREATE INDEX idx_messages_phone_iccid ON messages(phone_iccid);
CREATE INDEX idx_messages_type ON messages(type);
CREATE INDEX idx_messages_status ON messages(status);
CREATE INDEX idx_messages_timestamp ON messages(timestamp DESC);
CREATE INDEX idx_messages_verification_code ON messages(verification_code);
CREATE INDEX idx_messages_created_at ON messages(created_at DESC);
CREATE TRIGGER update_modems_timestamp 
AFTER UPDATE ON modems
BEGIN
    UPDATE modems SET updated_at = CURRENT_TIMESTAMP WHERE equipment_id = NEW.equipment_id;
END;
CREATE TRIGGER update_sims_timestamp 
AFTER UPDATE ON sims
BEGIN
    UPDATE sims SET updated_at = CURRENT_TIMESTAMP WHERE iccid = NEW.iccid;
END;
CREATE TRIGGER update_modem_state_timestamp 
AFTER UPDATE ON modem_state
BEGIN
    UPDATE modem_state SET updated_at = CURRENT_TIMESTAMP WHERE modem_id = NEW.modem_id;
END;
CREATE TRIGGER sim_swap_detection
AFTER UPDATE ON sims
WHEN OLD.current_modem_id != NEW.current_modem_id OR 
     (OLD.current_modem_id IS NULL AND NEW.current_modem_id IS NOT NULL) OR
     (OLD.current_modem_id IS NOT NULL AND NEW.current_modem_id IS NULL)
BEGIN
    -- Close previous association if exists
    UPDATE modem_sim_history 
    SET removed_at = CURRENT_TIMESTAMP
    WHERE modem_id = OLD.current_modem_id 
      AND sim_iccid = NEW.iccid
      AND removed_at IS NULL;
    
    -- Create new association if SIM is inserted into a modem
    SELECT NEW.current_modem_id, NEW.iccid
    WHERE NEW.current_modem_id IS NOT NULL;
END;
CREATE VIEW device_stats AS
SELECT 
  COUNT(DISTINCT m.equipment_id) as total_modems,
  COUNT(DISTINCT CASE WHEN m.status = 'connected' THEN m.equipment_id END) as connected_modems,
  COUNT(DISTINCT s.iccid) as total_sims,
  COUNT(DISTINCT CASE WHEN s.status = 'active' THEN s.iccid END) as active_sims,
  COUNT(DISTINCT CASE 
    WHEN m.status = 'connected' AND s.status = 'active' AND ms.connection_status = 'registered' 
    THEN m.equipment_id 
  END) as online_devices,
  AVG(CASE WHEN ms.signal_percent IS NOT NULL THEN ms.signal_percent END) as avg_signal_strength
FROM modems m
LEFT JOIN sims s ON s.current_modem_id = m.equipment_id
LEFT JOIN modem_state ms ON ms.modem_id = m.equipment_id;
CREATE VIEW device_view AS
SELECT 
  -- Primary identifier (use SIM iccid if available, otherwise modem id)
  COALESCE(s.iccid, 'NO_SIM_' || m.equipment_id) as id,
  
  -- Legacy fields for backward compatibility
  s.iccid,
  s.phone_number as number,
  s.country_code as country,
  CASE 
    WHEN s.country_code = 'CN' THEN '🇨🇳'
    WHEN s.country_code = 'US' THEN '🇺🇸'
    WHEN s.country_code = 'SG' THEN '🇸🇬'
    WHEN s.country_code = 'HK' THEN '🇭🇰'
    ELSE '🌍'
  END as flag,
  s.carrier,
  s.operator_name,
  s.operator_id,
  
  -- Status calculation - Fixed to handle 'registered' modem status
  CASE 
    WHEN (m.status = 'connected' OR m.status = 'registered') AND s.status = 'active' AND ms.connection_status = 'registered' THEN 'online'
    WHEN (m.status = 'connected' OR m.status = 'registered') AND s.status = 'active' THEN 'registered'
    WHEN (m.status = 'connected' OR m.status = 'registered') AND s.iccid IS NULL THEN 'sim-missing'
    WHEN m.status = 'disconnected' THEN 'offline'
    ELSE 'error'
  END as status,
  
  -- Signal data
  ms.signal_percent as signal,
  ms.rssi,
  ms.rsrq,
  ms.rsrp,
  ms.snr,
  ms.network_type,
  ms.access_tech,
  
  -- Modem information
  m.equipment_id as imei,
  m.equipment_id as modem_id,
  m.manufacturer as modem_manufacturer,
  m.model as modem_model,
  m.firmware_revision,
  m.usb_port,
  m.modem_index,
  m.status as modem_status,
  m.error_count as modem_error_count,
  m.last_error as modem_last_error,
  
  -- SIM information
  s.iccid as sim_iccid,
  s.phone_number as sim_phone_number,
  s.status as sim_status,
  s.activation_date as sim_activation_date,
  s.sim_index,
  
  -- Timestamps
  m.updated_at as modem_updated_at,
  s.updated_at as sim_updated_at,
  ms.updated_at as state_updated_at,
  CASE 
    WHEN m.updated_at >= s.updated_at AND m.updated_at >= ms.updated_at THEN m.updated_at
    WHEN s.updated_at >= ms.updated_at THEN s.updated_at
    ELSE ms.updated_at
  END as updated_at
FROM modems m
LEFT JOIN sims s ON s.current_modem_id = m.equipment_id
LEFT JOIN modem_state ms ON ms.modem_id = m.equipment_id
ORDER BY 
  CASE WHEN m.usb_port IS NOT NULL THEN m.usb_port ELSE 999 END,
  s.iccid;
